/**
 * The models the site lists (docs/SPEC.md §4.1). Two files, both read by the
 * build and the Node scripts, never fetched:
 *
 *   data/models.json            generated by `pnpm sync` from the sources
 *                               (scripts/lib/discover.ts); do not edit
 *   data/model-overrides.yaml   hand-written corrections: models to leave
 *                               out or add, fields and mappings to replace,
 *                               statuses, price overrides, maker aliases
 *
 * A model is `legacy` when the list has a newer version of it: same vendor,
 * same name once the version number is taken out, higher version
 * ("Claude Opus 5" next to "Claude Opus 5.5"). An override's status wins.
 *
 * Must not import `astro:*` modules (the Node scripts use this too).
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { z } from 'astro/zod';
import { parse as parseYaml } from 'yaml';
import { modelSchema, type ModelEntry } from './model-schema';

export const MODEL_LIST_FILE = 'data/models.json';
export const MODEL_OVERRIDES_FILE = 'data/model-overrides.yaml';

const SOURCE_FIELDS = [
  'modelsdev',
  'aa',
  'arena_text',
  'arena_webdev',
  'arena_agent',
  'livebench',
] as const;

/** One generated model: what discovery found. */
export const generatedModelSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  vendor: z.string().min(1),
  sources: z.partialRecord(z.enum(SOURCE_FIELDS), z.string().min(1)).default({}),
});
export type GeneratedModel = z.infer<typeof generatedModelSchema>;

export const modelListSchema = z.object({ models: z.array(generatedModelSchema) });

const price = z.object({
  input: z.number().min(0),
  output: z.number().min(0),
  cache_read: z.number().min(0).optional(),
});

/** One model's corrections. A source set to null means "not on that leaderboard". */
const modelOverrideSchema = z
  .object({
    name: z.string().min(1).optional(),
    vendor: z.string().min(1).optional(),
    status: z.enum(['active', 'legacy']).optional(),
    sources: z.partialRecord(z.enum(SOURCE_FIELDS), z.string().min(1).nullable()).optional(),
    price: price.optional(),
  })
  .strict();

export const overridesSchema = z
  .object({
    /** Model IDs never listed, even when discovery finds them. */
    exclude: z.array(z.string().min(1)).default([]),
    /** Maker name → models.dev provider ID, where the two differ. */
    aliases: z.record(z.string(), z.string()).default({}),
    /** Per-model corrections, keyed by model ID. An ID discovery did not find is added. */
    models: z.record(z.string(), modelOverrideSchema).default({}),
  })
  .strict();
export type ModelOverrides = z.infer<typeof overridesSchema>;

export const EMPTY_OVERRIDES: ModelOverrides = { exclude: [], aliases: {}, models: {} };

/** Validate one model; throws with `where` in the message. */
export function parseModelEntry(id: string, raw: unknown, where = id): ModelEntry {
  const parsed = modelSchema.safeParse(raw ?? {});
  if (!parsed.success) {
    const issues = parsed.error.issues
      .map((issue) => `  - ${issue.path.join('.') || '(root)'}: ${issue.message}`)
      .join('\n');
    throw new Error(`${where}: invalid model\n${issues}`);
  }
  return { id, data: parsed.data };
}

/** The name without its version number, and the version as numbers. */
export function versionOf(name: string): { family: string; version: number[] | null } {
  const family: string[] = [];
  let version: number[] | null = null;
  for (const token of name.split(/[\s-]+/).filter(Boolean)) {
    const match = /^([a-z]*)(\d+(?:\.\d+)*)$/i.exec(token);
    if (match && version === null) {
      version = match[2]!.split('.').map(Number);
      if (match[1]) family.push(match[1].toLowerCase());
    } else if (!/^(preview|exp|experimental|latest)$/i.test(token)) {
      family.push(token.toLowerCase());
    }
  }
  return { family: family.join(' '), version };
}

function compareVersions(a: number[], b: number[]): number {
  for (let i = 0; i < Math.max(a.length, b.length); i += 1) {
    const diff = (a[i] ?? 0) - (b[i] ?? 0);
    if (diff !== 0) return diff;
  }
  return 0;
}

/** Corrections for models that are neither in the generated list nor added by hand. */
export function waitingOverrides(generated: GeneratedModel[], overrides: ModelOverrides): string[] {
  const ids = new Set(generated.map((model) => model.id));
  return Object.entries(overrides.models)
    .filter(([id, fix]) => !ids.has(id) && !(fix.name && fix.vendor))
    .map(([id]) => id);
}

/** IDs of the models the list has a newer version of. */
export function supersededIds(models: { id: string; name: string; vendor: string }[]): Set<string> {
  const parsed = models.map((model) => ({ ...model, ...versionOf(model.name) }));
  const superseded = new Set<string>();
  for (const model of parsed) {
    if (model.version === null) continue;
    const newer = parsed.some(
      (other) =>
        other.vendor === model.vendor &&
        other.family === model.family &&
        other.version !== null &&
        compareVersions(other.version, model.version!) > 0,
    );
    if (newer) superseded.add(model.id);
  }
  return superseded;
}

/** The generated list with the corrections applied, validated and sorted by ID. */
export function mergeModelList(
  generated: GeneratedModel[],
  overrides: ModelOverrides = EMPTY_OVERRIDES,
): ModelEntry[] {
  const excluded = new Set(overrides.exclude);
  const byId = new Map<string, GeneratedModel>();
  for (const model of generated) {
    if (!excluded.has(model.id)) byId.set(model.id, model);
  }

  const drafts: { id: string; name: string; vendor: string; raw: Record<string, unknown> }[] = [];
  const ids = new Set([...byId.keys(), ...Object.keys(overrides.models)]);
  for (const id of ids) {
    if (excluded.has(id)) continue;
    const base = byId.get(id);
    const fix = overrides.models[id] ?? {};
    const name = fix.name ?? base?.name;
    const vendor = fix.vendor ?? base?.vendor;
    // A correction for a model that is not listed waits until it is, unless
    // it carries a name and a vendor, which add the model by hand.
    if (!name || !vendor) continue;
    const sources: Record<string, string> = { ...base?.sources };
    for (const [field, value] of Object.entries(fix.sources ?? {})) {
      if (value === null) delete sources[field];
      else if (value !== undefined) sources[field] = value;
    }
    drafts.push({
      id,
      name,
      vendor,
      raw: {
        name,
        vendor,
        status: fix.status,
        sources,
        overrides: fix.price ? { price: fix.price } : {},
      },
    });
  }

  const superseded = supersededIds(drafts);
  return drafts
    .map(({ id, raw }) =>
      parseModelEntry(
        id,
        { ...raw, status: raw.status ?? (superseded.has(id) ? 'legacy' : 'active') },
        `${MODEL_LIST_FILE} (${id})`,
      ),
    )
    .sort((a, b) => a.id.localeCompare(b.id));
}

function readText(path: string): string | null {
  try {
    return readFileSync(path, 'utf8');
  } catch {
    return null;
  }
}

/** The generated list; empty when the file is missing. Throws when it is invalid. */
export function readGeneratedList(root: string = process.cwd()): GeneratedModel[] {
  const text = readText(join(root, MODEL_LIST_FILE));
  if (text === null) return [];
  const parsed = modelListSchema.safeParse(JSON.parse(text));
  if (!parsed.success) {
    throw new Error(`${MODEL_LIST_FILE} is invalid: ${parsed.error.issues[0]?.message}`);
  }
  return parsed.data.models;
}

/** The corrections; none when the file is missing. Throws when it is invalid. */
export function readOverrides(root: string = process.cwd()): ModelOverrides {
  const text = readText(join(root, MODEL_OVERRIDES_FILE));
  if (text === null) return EMPTY_OVERRIDES;
  const parsed = overridesSchema.safeParse(parseYaml(text) ?? {});
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    throw new Error(
      `${MODEL_OVERRIDES_FILE} is invalid at ${issue?.path.join('.') || '(root)'}: ${issue?.message}`,
    );
  }
  return parsed.data;
}

/** Every model the site lists. */
export function readModelList(root: string = process.cwd()): ModelEntry[] {
  return mergeModelList(readGeneratedList(root), readOverrides(root));
}

/** The generated list as written to data/models.json. */
export function serializeModelList(models: GeneratedModel[]): string {
  const sorted = [...models].sort((a, b) => a.id.localeCompare(b.id));
  return `${JSON.stringify({ models: sorted }, null, 2)}\n`;
}
